# Search for IMF data - Germany's GDP 1991 and 1996
curl -s "https://dataservices.imf.org/REST/SDMX_JSON.svc/CompactData/IFS/NY.GDP.MKTP.CD.DE" | python3 -c "
import json,sys
try:
    data = json.load(sys.stdin)
    if 'Structure' in data:
        print('IMF data format not compact')
    else:
        obs = data.get('CompactData',{}).get('DataSet',{}).get('Series',[])
        for s in obs:
            if 'Obs' in s:
                for o in s['Obs']:
                    if o.get('@TIME_PERIOD') in ['1991','1996']:
                        print(f\"{o.get('@TIME_PERIOD')}: {o.get('@OBS_VALUE')}\")
except Exception as e:
    print(f'Error: {e}')
"

